import fs from 'node:fs/promises';import path from 'node:path';import http from 'node:http';import assert from 'node:assert/strict';
import {chromium} from '../../.local/browser-test/node_modules/playwright-core/index.mjs';
const root=path.resolve('.local/media-errors-20260920/candidate/student'),out=path.resolve('evidence/media-errors-20260920');
const server=http.createServer(async(req,res)=>{try{const pathname=new URL(req.url,'http://localhost').pathname;if(pathname==='/'){res.setHeader('Content-Type','text/html');res.end('<meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/css/tokens.css"><link rel="stylesheet" href="/css/components.css"><link rel="stylesheet" href="/css/screens.css"><main id="content" style="padding:20px"></main>');return;}const file=path.resolve(root,'.'+pathname);assert.ok(file.startsWith(root+path.sep));res.setHeader('Content-Type',file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':'application/octet-stream');res.end(await fs.readFile(file));}catch{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));
const browser=await chromium.launch({executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',headless:true});const page=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});const errors=[];page.on('pageerror',e=>errors.push(e.message));
try{await page.goto('http://127.0.0.1:'+server.address().port);
const result=await page.evaluate(async()=>{const screen=await import('/js/screens/checkin.js'),api=await import('/js/api.js'),ui=await import('/js/ui.js'),session=await import('/js/session.js');
const app={ui:{},state:{workspace:{student:{id:'synthetic'},courses:[],proofTodos:[],creditPolicy:{minCreditThresholdMinutes:30}}},isWriteAllowed:()=>true};session.saveSession('synthetic',{serverId:'synthetic',phase:'finished',startedAt:Date.now()-3600000,endedAt:Date.now(),activeDurationMillis:3600000,details:{creditType:'general',sportType:'running',description:'合成测试'}});screen.renderCheckIn(app);app.ui.checkin.drafts=[{id:'failed-video',type:'video',byteCount:2000000,url:'',processingFailure:{code:'MEDIA_VIDEO_DURATION_EXCEEDED',mediaId:'synthetic'}}];
const model=api.toUserFacingError(new api.ApiError(422,{code:'MEDIA_FAILURE_NOT_RETRYABLE',details:{failureCode:'MEDIA_VIDEO_DURATION_EXCEEDED'}}),{log:false});window.qa={app,screen};document.querySelector('#content').innerHTML=ui.userFacingErrorPanel(model)+screen.renderCheckIn(app);return {code:model.code};});assert.equal(result.code,'MEDIA_VIDEO_DURATION_EXCEEDED');assert.match(await page.locator('body').innerText(),/1–10/);assert.equal(await page.getByRole('button',{name:/预览现场视频，校验失败/}).count(),1);assert.doesNotMatch(await page.locator('body').innerText(),/修正标记/);await page.screenshot({path:out+'/mobile-error.png',fullPage:true});
await page.evaluate(()=>{const {app,screen}=window.qa;app.ui.checkin.previewDraftId='failed-video';document.querySelector('#content').innerHTML=screen.renderCheckIn(app);});assert.equal(await page.getByRole('button',{name:'删除该凭证',exact:true}).isEnabled(),true);assert.match(await page.locator('[role="alert"]').innerText(),/1–10/);await page.screenshot({path:out+'/mobile-replace.png',fullPage:true});assert.deepEqual(errors,[]);await fs.writeFile(out+'/browser.json',JSON.stringify({result:'PASS',mobileWidth:390,failureMarked:true,specificReason:true,deleteEnabled:true,pageErrors:errors,scope:'Synthetic browser UI; no production student writes'},null,2));console.log('Mobile browser checks PASS');}finally{await browser.close();await new Promise(r=>server.close(r));}
